// Drossel vor Telegram und Gedaechtnis (Runde 11 Teilrunde 2, B40, E4).
// Je Workflow und Fehlertext hoechstens eine Meldung je Stunde; Wiederholungen
// zaehlt dieser Knoten nur (wiederholt in der Zeile der ersten Meldung). Je
// Workflow hoechstens DECKEL Meldungen und Zeilen je Stunde; was darueber
// kommt, steht als ueber_deckel in einer dieser Zeilen.
// Die Zeile zur Meldung legt dieser Knoten an, BEVOR Telegram sendet (telegram
// ausstehend), und liest danach ein zweites Mal: laufen Fehler desselben
// Workflows gleichzeitig, sieht der spaetere die fruehere Zeile (kleinere id)
// und nimmt seine eigene zurueck. So halten Drossel und Deckel auch bei
// gleichzeitigen Fehlern; offen bleibt nur ein Fenster von Millisekunden, in
// dem eine fruehere Zeile noch nicht sichtbar ist. Zum Deckel zaehlen nur
// Zeilen, die bleiben, nie eine Reservierung, die ihr Lauf gleich
// zuruecknimmt; sonst ginge bei gleichzeitigen Fehlern eine zweite Fehlerart
// unter dem Deckel verloren. Gelesen werden die aeltesten Zeilen zuerst (id
// aufsteigend): sie entscheiden, auch wenn mehr als 50 gleichzeitig laufen.
// "Log Error to memory_long" traegt danach ein, ob Telegram zugestellt hat;
// eine nicht zugestellte Meldung schaltet die Stunde nicht stumm, der Deckel
// zaehlt sie mit. Dasselbe gilt fuer eine Reservierung, die nach JUNG_MS noch
// ausstehend ist (Ausfuehrung abgebrochen, Antwort der Datenbank zu spaet).
// Schluessel: Workflow-ID plus Pruefsumme des Fehlertexts. In der Adresse steht
// nur die Workflow-ID, nie der Text.
// Ist die Datenbank nicht erreichbar oder antwortet sie unlesbar, geht nichts
// raus: diesen Fall meldet der Container-Waechter (ops/claw-wacht.sh), und ohne
// Drossel kaemen sonst Hunderte Meldungen (Reminder Runner am 25.09.2026: 501
// Fehlschlaege). Der Knoten wirft nie; ohne Ausgabe laufen Telegram und Log
// nicht. Die Error Notification hat selbst keinen Fehler-Workflow, also keine
// Schleife.
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const KOPF = { apikey: SUPABASE_KEY, Authorization: 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };
const TABELLE = SUPABASE_URL + '/rest/v1/memory_long';
const STUNDE_MS = 3600 * 1000;
const ABLAUF_MS = 30 * 24 * 3600 * 1000;
const DECKEL = 3;
// So lange gilt eine Reservierung (telegram ausstehend) als laufende Meldung.
const JUNG_MS = 2 * 60 * 1000;

// Variable Teile (Kennungen, Zeitstempel, lange Zahlen) fallen weg, damit
// Wiederholungen denselben Schluessel bekommen; Statuscodes bleiben.
function fehlerText(s) {
  return String(s || '').toLowerCase()
    .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g, '#')
    .replace(/\d{4}-\d{2}-\d{2}[t ]\d{2}:\d{2}(:\d{2}(\.\d+)?)?(z|[+-]\d{2}:?\d{2})?/g, '#')
    .replace(/\b\d{1,2}:\d{2}(:\d{2})?\b/g, '#')
    .replace(/\d{5,}/g, '#')
    .replace(/\s+/g, ' ').trim().slice(0, 300);
}
// FNV-1a von Hand: der Code-Knoten hat kein crypto.
function fnv1a(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return ('0000000' + h.toString(16)).slice(-8);
}

const ein = $input.first();
const j = (ein && ein.json) || {};
const wf = j.workflow || {};
const trig = j.trigger || {};
// Ausloeserfehler (Trigger) tragen kein execution: fuer Telegram und den
// Vermerk nachbilden, damit deren Ausdruecke nicht an execution.error scheitern.
const exec = j.execution || { id: null, url: null, mode: trig.mode || 'trigger',
  lastNodeExecuted: (trig.error && trig.error.node && trig.error.node.name) || null, error: trig.error || {} };
const err = exec.error || {};
const wfKennung = String(wf.id || wf.name || 'unbekannt').replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 64);
const schluessel = 'en:' + wfKennung + ':' + fnv1a(fehlerText(err.message || err.description || 'unbekannter Fehler'));
const seit = new Date(Date.now() - STUNDE_MS).toISOString();
const FILTER = '?scope=eq.betrieb&category=eq.error&metadata-%3E%3Ewf_kennung=eq.' + encodeURIComponent(wfKennung)
  + '&created_at=gt.' + encodeURIComponent(seit) + '&select=id,metadata,created_at&order=id.asc&limit=50';

async function zeilenLesen() {
  const z = await helpers.httpRequest({ method: 'GET', url: TABELLE + FILTER, headers: KOPF, json: true, timeout: 5000 });
  if (!Array.isArray(z)) throw new Error('keine Liste');
  return z.filter(r => r && r.metadata && typeof r.metadata === 'object');
}
const nachId = (liste) => liste.slice().sort((a, b) => Number(a.id) - Number(b.id));
// Stumm schaltet nur eine zugestellte Meldung (ok) oder eine, die gerade
// laeuft (ausstehend und juenger als JUNG_MS); fehler, unbekannt und eine
// haengengebliebene Reservierung zaehlen nur beim Deckel mit. Ist die Zeit der
// Zeile nicht lesbar, gilt die Reservierung als laufend (dann bleibt es bei
// einer Meldung).
function stumm(z) {
  if (z.metadata.telegram === 'ok') return true;
  if (z.metadata.telegram !== 'ausstehend') return false;
  return !(Date.now() - Date.parse(z.created_at) >= JUNG_MS);
}
// Gezaehlt wird an der aeltesten passenden Zeile (eine juengere kann eine
// Reservierung sein, die gleich zurueckgenommen wird).
function gleicheVon(liste) {
  return nachId(liste).find(z => z.metadata.schluessel === schluessel && stumm(z));
}
// Die Zeilen, die bleiben: eine stumm schaltende Zeile mit dem Schluessel einer
// frueheren stumm schaltenden ist eine Reservierung, die ihr Lauf gleich
// zuruecknimmt, und zaehlt nicht zum Deckel.
function bleibende(liste) {
  const gesehen = new Set();
  return nachId(liste).filter(z => {
    if (!stumm(z)) return true;
    if (gesehen.has(z.metadata.schluessel)) return false;
    gesehen.add(z.metadata.schluessel);
    return true;
  });
}
// Ueber dem Deckel: an der juengsten der DECKEL aeltesten bleibenden Zeilen
// zaehlen.
function deckelZiel(liste) {
  const z = bleibende(liste).slice(0, DECKEL);
  return z[z.length - 1];
}
// metadata einer Zeile aendern, aber nur, wenn telegram, wiederholt und
// ueber_deckel noch so stehen wie eben gelesen; sonst neu lesen, hoechstens
// dreimal. So ueberschreibt ein Zaehler nie den Zustellvermerk und umgekehrt.
async function metadataAendern(id, aendern) {
  for (let versuch = 0; versuch < 3; versuch++) {
    const z = await helpers.httpRequest({ method: 'GET', url: TABELLE + '?id=eq.' + id + '&select=metadata',
      headers: KOPF, json: true, timeout: 5000 });
    const alt = Array.isArray(z) && z[0] && z[0].metadata && typeof z[0].metadata === 'object' ? z[0].metadata : null;
    if (!alt) return false;
    const bedingung = ['telegram', 'wiederholt', 'ueber_deckel'].map(f => '&metadata-%3E%3E' + f
      + (alt[f] === undefined || alt[f] === null ? '=is.null' : '=eq.' + encodeURIComponent(String(alt[f])))).join('');
    const r = await helpers.httpRequest({ method: 'PATCH', url: TABELLE + '?id=eq.' + id + bedingung + '&select=id',
      headers: Object.assign({ Prefer: 'return=representation' }, KOPF),
      body: JSON.stringify({ metadata: aendern(Object.assign({}, alt)) }), json: true, timeout: 5000 });
    if (Array.isArray(r) && r.length) return true;
  }
  return false;
}
async function zaehlen(ziel, feld) {
  try {
    await metadataAendern(Number(ziel.id), m => {
      m[feld] = (Number(m[feld]) || 0) + 1;
      m.zuletzt = new Date().toISOString();
      return m;
    });
  } catch (_e) {}
  return [];
}
async function zuruecknehmen(id) {
  try {
    await helpers.httpRequest({ method: 'DELETE', url: TABELLE + '?id=eq.' + Number(id),
      headers: Object.assign({ Prefer: 'return=minimal' }, KOPF), json: false, timeout: 5000 });
  } catch (_e) {}
}

let vorher;
try { vorher = await zeilenLesen(); } catch (_e) { return []; }
let ziel = gleicheVon(vorher);
if (ziel) return zaehlen(ziel, 'wiederholt');
if (bleibende(vorher).length >= DECKEL) return zaehlen(deckelZiel(vorher), 'ueber_deckel');

// Die Zeile zur Meldung anlegen, bevor Telegram sendet. Lesbarer Text wie
// bisher, dazu die Felder der Drossel.
const zeit = new Date().toISOString().replace('T', ' ').slice(0, 16);
const content = `Workflow error in "${wf.name}" at ${zeit} UTC: ${err.message || 'unknown error'}. Failed at node "${exec.lastNodeExecuted || 'n/a'}". Execution ${exec.id || 'n/a'}: ${exec.url || 'n/a'}`;
const metadata = {
  execution_id: exec.id || null,
  execution_url: exec.url || null,
  execution_mode: exec.mode || null,
  workflow_id: wf.id || null,
  workflow_name: wf.name || null,
  node_name: exec.lastNodeExecuted || null,
  error_name: err.name || null,
  error_message: err.message || null,
  error_stack: err.stack ? String(err.stack).slice(0, 2000) : null,
  schluessel,
  wf_kennung: wfKennung,
  telegram: 'ausstehend',
  wiederholt: 0,
  ueber_deckel: 0
};
// scope betrieb liefert die Memory Search nicht aus (E4); Ablauf nach 30 Tagen,
// die naechtliche Konsolidierung loescht abgelaufene Zeilen. Kein entity_name
// und kein owner_user_id: der Entity Manager liest memory_long nach entity_name
// ohne scope, und mit owner_user_id saehe die Besitzerin die Zeile in der Suche.
let eigene = NaN;
try {
  const r = await helpers.httpRequest({ method: 'POST', url: TABELLE + '?select=id',
    headers: Object.assign({ Prefer: 'return=representation' }, KOPF),
    body: JSON.stringify({ content, category: 'error', importance: 8, scope: 'betrieb', source: 'error_notification',
      expires_at: new Date(Date.now() + ABLAUF_MS).toISOString(),
      tags: ['error', 'workflow-failure', String(wf.name || 'unbekannt')], metadata }),
    json: true, timeout: 5000 });
  eigene = Number(Array.isArray(r) && r[0] ? r[0].id : NaN);
} catch (_e) { return []; }
if (!Number.isFinite(eigene)) return [];

// Zweites Lesen: eine fruehere Zeile mit gleichem Schluessel oder ein voller
// Deckel gewinnt, dann nimmt dieser Lauf seine Zeile zurueck und zaehlt nur.
// Ist die Datenbank jetzt nicht lesbar, geht ebenfalls nichts raus.
let davor;
try { davor = (await zeilenLesen()).filter(z => Number(z.id) < eigene); } catch (_e) { await zuruecknehmen(eigene); return []; }
ziel = gleicheVon(davor);
if (ziel || bleibende(davor).length >= DECKEL) {
  await zuruecknehmen(eigene);
  return ziel ? zaehlen(ziel, 'wiederholt') : zaehlen(deckelZiel(davor), 'ueber_deckel');
}
return [{ json: Object.assign({}, j, { execution: exec, _drossel: { id: eigene, schluessel, wf_kennung: wfKennung } }) }];

// Traegt in die Zeile, die "Drosseln" vor dem Senden angelegt hat, ein, ob die
// Telegram-Meldung zugestellt wurde: ok, fehler oder unbekannt (Runde 11
// Teilrunde 2, B40, E4). Nur ok (und eine noch laufende Meldung) schaltet die
// Stunde fuer diesen Fehler stumm; nach fehler oder unbekannt meldet der
// naechste gleiche Fehler wieder, der Deckel zaehlt beide Faelle mit.
// Ueber PostgREST wie Save Conversation and Log (wegen des pg-promise-Fehlers
// mit $N), mit apikey UND Authorization Bearer. Geschrieben wird nur, wenn
// telegram, wiederholt und ueber_deckel noch so stehen wie gelesen (sonst neu
// lesen, hoechstens dreimal): so gehen gleichzeitig gezaehlte Wiederholungen
// nicht verloren. Den Fehlertext von Telegram speichert der Knoten nicht.
// Laeuft nur, wenn "Drosseln" die Meldung durchgelassen hat.
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const KOPF = { apikey: SUPABASE_KEY, Authorization: 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };
const TABELLE = SUPABASE_URL + '/rest/v1/memory_long';

async function metadataAendern(id, aendern) {
  for (let versuch = 0; versuch < 3; versuch++) {
    const z = await helpers.httpRequest({ method: 'GET', url: TABELLE + '?id=eq.' + id + '&select=metadata',
      headers: KOPF, json: true, timeout: 5000 });
    const alt = Array.isArray(z) && z[0] && z[0].metadata && typeof z[0].metadata === 'object' ? z[0].metadata : null;
    if (!alt) return false;
    const bedingung = ['telegram', 'wiederholt', 'ueber_deckel'].map(f => '&metadata-%3E%3E' + f
      + (alt[f] === undefined || alt[f] === null ? '=is.null' : '=eq.' + encodeURIComponent(String(alt[f])))).join('');
    const r = await helpers.httpRequest({ method: 'PATCH', url: TABELLE + '?id=eq.' + id + bedingung + '&select=id',
      headers: Object.assign({ Prefer: 'return=representation' }, KOPF),
      body: JSON.stringify({ metadata: aendern(Object.assign({}, alt)) }), json: true, timeout: 5000 });
    if (Array.isArray(r) && r.length) return true;
  }
  return false;
}

const dr = ((($('Drosseln').first() || {}).json) || {})._drossel || {};
const tg = (($input.first() || {}).json) || {};
const zugestellt = tg.ok === true || !!(tg.result && tg.result.message_id) || !!tg.message_id;
const telegram = zugestellt ? 'ok' : (tg.error ? 'fehler' : 'unbekannt');
const id = Number(dr.id);
if (!Number.isFinite(id)) return [{ json: { logged: false, telegram } }];
let logged = false;
try {
  logged = await metadataAendern(id, m => {
    m.telegram = telegram;
    m.telegram_am = new Date().toISOString();
    return m;
  });
} catch (_e) {}
return [{ json: { logged, id, telegram } }];
